using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;

namespace ArcHive.Core;

// Deliberately not a record: autogenerated ToString must never expose secrets.
public sealed class ProviderCredentials
{
    public string SteamKey { get; set; } = "";
    public string IgdbClientId { get; set; } = "";
    public string IgdbClientSecret { get; set; } = "";
    public string ItchKey { get; set; } = "";
    public string RawgKey { get; set; } = "";
}

public sealed class WindowsProviderCredentialStore(string target = "ArcHive/MetadataProviders")
{
    public ProviderCredentials Load()
    {
        if (!CredRead(target, 1, 0, out var pointer))
        {
            if (Marshal.GetLastWin32Error() == 1168) return new();
            throw new ProviderException($"Windows Credential Manager could not read provider settings (Windows error {Marshal.GetLastWin32Error()}).");
        }
        try
        {
            var credential = Marshal.PtrToStructure<Credential>(pointer);
            if (credential.BlobSize > 2560) throw new ProviderException("Saved provider settings are invalid.");
            var bytes = new byte[credential.BlobSize];
            try
            {
                Marshal.Copy(credential.Blob, bytes, 0, bytes.Length);
                return JsonSerializer.Deserialize<ProviderCredentials>(bytes) ?? new();
            }
            catch (JsonException) { throw new ProviderException("Saved provider settings are invalid."); }
            finally { Array.Clear(bytes); }
        }
        finally { CredFree(pointer); }
    }
    public void Save(ProviderCredentials settings)
    {
        var bytes = JsonSerializer.SerializeToUtf8Bytes(settings);
        try
        {
            if (bytes.Length > 2560) throw new ProviderException("Provider settings exceed Windows' credential size limit. Use shorter keys or session-only settings.");
            var pointer = Marshal.AllocHGlobal(bytes.Length);
            try
            {
                Marshal.Copy(bytes, 0, pointer, bytes.Length);
                var credential = new Credential { Type = 1, TargetName = target, UserName = "ArcHive", BlobSize = (uint)bytes.Length, Blob = pointer, Persist = 2 };
                if (!CredWrite(ref credential, 0)) throw new ProviderException($"Windows Credential Manager could not save provider settings (Windows error {Marshal.GetLastWin32Error()}).");
            }
            finally
            {
                Marshal.Copy(new byte[bytes.Length], 0, pointer, bytes.Length); Marshal.FreeHGlobal(pointer);
            }
        }
        finally { Array.Clear(bytes); }
    }
    public void Delete()
    {
        if (!CredDelete(target, 1, 0) && Marshal.GetLastWin32Error() != 1168)
            throw new ProviderException($"Windows Credential Manager could not remove provider settings (Windows error {Marshal.GetLastWin32Error()}).");
    }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    private struct Credential
    {
        public uint Flags, Type;
        public string TargetName;
        public string? Comment;
        public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;
        public uint BlobSize;
        public IntPtr Blob;
        public uint Persist, AttributeCount;
        public IntPtr Attributes;
        public string? TargetAlias;
        public string UserName;
    }
    [DllImport("advapi32.dll", EntryPoint = "CredReadW", CharSet = CharSet.Unicode, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)] private static extern bool CredRead(string target, uint type, uint flags, out IntPtr credential);
    [DllImport("advapi32.dll", EntryPoint = "CredWriteW", CharSet = CharSet.Unicode, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)] private static extern bool CredWrite(ref Credential credential, uint flags);
    [DllImport("advapi32.dll", EntryPoint = "CredDeleteW", CharSet = CharSet.Unicode, SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)] private static extern bool CredDelete(string target, uint type, uint flags);
    [DllImport("advapi32.dll")] private static extern void CredFree(IntPtr credential);
}
